        throw new BubbleSortError('Input is required. Please provide an array.');
    }

    // Check if input is an array
    if (!Array.isArray(arr)) {
        throw new BubbleSortError(`Invalid input type. Expected an array but received ${typeof arr}.`);
    }

    // Check array length
    if (arr.length === 0) {
        throw new BubbleSortError('Array cannot be empty. Please provide at least one element.');
    }

    if (arr.length > MAX_ARRAY_LENGTH) {
        throw new BubbleSortError(`Array length exceeds maximum limit. Maximum allowed: ${MAX_ARRAY_LENGTH}, Received: ${arr.length}.`);
    }

    // Validate each element in the array
    for (let i = 0; i < arr.length; i++) {
        const element = arr[i];

        // Check if element is a number
        if (typeof element !== 'number') {
            throw new BubbleSortError(`Invalid element at index ${i}. Expected a number but received ${typeof element}.`);
        }

        // Check if element is not NaN
        if (Number.isNaN(element)) {
            throw new BubbleSortError(`Invalid element at index ${i}. NaN is not allowed.`);
        }

        // Check if element is finite
        if (!Number.isFinite(element)) {
            throw new BubbleSortError(`Invalid element at index ${i}. Infinity values are not allowed.`);
        }

        // Check if element is an integer
        if (!Number.isInteger(element)) {
            throw new BubbleSortError(`Invalid element at index ${i}. Expected an integer but received a floating-point number (${element}).`);
        }

        // Check if element is within valid range
